from pathlib import Path
import json,base64,re
P=Path(__file__).parent
S=[]
def add(title,body,notes,seconds):S.append(dict(title=title,body=body,notes=notes,seconds=seconds))
def img(name,cls='',style=''):return f'<img class="{cls}" style="{style}" src="assets/{name}">'
def portrait(role):return f'<img src="../../../office/public/portraits/{role}.png">'
def label(t):return '<div class="label">'+t+'</div>'
add('Give AI a team.', '<div class="hero-copy">'+label('AGENTIC SOFTWARE FACTORY')+'<h1>One idea.<br>A whole<br><em>engineering team.</em></h1><p>Coordinated work.<br>Visible progress.</p></div><div class="hero-screen">'+img('realm-working.png')+'</div><div class="hero-bottom">One Idea. Multiple Agents. One Software Factory.</div>', 'AI can write code. But someone still has to define the product, coordinate tasks, inspect changes and test the result. Agentic Software Factory gives that work a team structure. Specialized agents operate inside a controlled workflow, while FORGE Realm makes their activity visible. Today we will show seven practical advantages, one architecture view, and the actual frontend in motion. The recording is a real UI replay, not a new live model-backed build.',25)
add('Every role owns<br>a clear outcome.', label('SPECIALIZED OWNERSHIP')+'<h1>Every role owns<br><em>a clear outcome.</em></h1><div class="role-line">'+''.join('<div>'+portrait(r)+f'<h3>{t}</h3><p>{x}</p></div>' for r,t,x in [('product','Product','Acceptance criteria'),('architect','Architect','Contracts + tasks'),('dev-1','Developer','Code + unit tests'),('qa','QA','Feature verification')])+'</div><div class="example"><span>EXAMPLE · TASK-MANAGER REQUEST</span><strong>“Add tasks” → define behavior → design contract → implement → test</strong></div>', 'The first advantage is clear ownership. For an illustrative task-manager request, Product defines what adding a task should do. Architecture establishes the data contract and decomposes the work. Development implements the assigned files and unit tests. QA checks behavior independently. These are role-contract examples, not a claim that this task-manager application was built in our recording. The implementation also includes research, UI/UX, review, integration and DevOps roles.',28)
add('The workflow has<br>an authority.', label('CONTROLLED ORCHESTRATION')+'<h1>The workflow has<br><em>an authority.</em></h1><div class="authority"><div class="big-node">Deterministic<br>orchestrator</div><div class="authority-rules"><p>Dependencies decide readiness.</p><p>File lanes define ownership.</p><p>Budget constrains execution.</p></div></div><div class="example"><span>EXAMPLE · BEFORE PARALLEL DEVELOPMENT</span><strong>Overlapping file lanes? Serialize the tasks.</strong></div>', 'Agents generate work; deterministic code decides when that work can run. Task dependencies, file lanes, phase order and budget rules remain authoritative. For example, before parallel development, the contract gate examines overlapping file lanes and adds ordering. If that creates a dependency cycle, it falls back to one-at-a-time execution. This is a code-backed control, not a promise that every model decision is correct. Experimental Jev suggestions do not override these rules.',28)
add('Build compatible<br>tasks together.', label('PARALLEL EXECUTION')+'<h1>Build compatible<br><em>tasks together.</em></h1><div class="parallel-top">Ready tasks · independent lanes · configurable concurrency</div><div class="lanes">'+''.join(f'<div><span>{a}</span><h3>{b}</h3><p>{c}</p><div class="branch-arrow">↓</div></div>' for a,b,c in [('T1 / WORKTREE A','Proxy + replay server','Backend access'),('T2 / WORKTREE B','Reducer + handoffs','State transitions'),('T3 / WORKTREE C','HUD + controls','Frontend interaction')])+'</div><div class="merge-line">Checks + policy review → Serialized merge → Main gate</div><p class="footnote">Actual task examples from the Living Foundry recording. No speedup benchmark claimed.</p>', 'Parallel work is supported where tasks are compatible. The Living Foundry recording shows T1 for the proxy and replay server, T2 for the reducer and handoffs, and T3 for the data hook, HUD and controls. They enter running status before their developer sessions start. Each developer works in a separate Git worktree. Integration is serialized and main is checked again. This enables concurrency; it does not establish a measured speedup or complete isolation from shared host resources.',30)
add('See the work<br>behind the character.', label('WORKFLOW VISIBILITY')+'<h1>See what each <em>agent is doing.</em></h1><div class="visibility-frame">'+img('realm-agent-expanded.png')+'</div><div class="visibility-aside"><div><b>WHO</b><p>Selected agent</p></div><div><b>WHAT</b><p>Task + tool activity</p></div><div><b>WHERE NEXT</b><p>Review and QA stages</p></div></div><div class="under-screen">Actual frontend · recorded sample replay · expandable activity</div>', 'FORGE Realm is the visibility layer. Clicking a character opens its task context and recent activity. Expanding a recorded activity row reveals details such as phase, task and tool. Operators can move between the world, the task board and agent logs to understand what is happening. This capture is the actual frontend playing recorded sample events. Character movement makes activity understandable, while the underlying log is what supports an engineering claim.',30)
add('“Done” should come<br>with evidence.', label('INSPECTABLE OUTCOMES')+'<h1>“Done” should come<br><em>with evidence.</em></h1><div class="evidence-track"><div><span>01</span><h3>Gate passed</h3><p>Recorded check event</p></div><b>→</b><div><span>02</span><h3>Review approved</h3><p>Recorded verdict</p></div><b>→</b><div><span>03</span><h3>Merged</h3><p>Task status + sample state</p></div></div><div class="example"><span>ACTUAL SAMPLE · T1 / PROXY + REPLAY SERVER</span><strong>A traceable task outcome, with its limits visible.</strong></div><p class="footnote">This trace does not establish feature-level QA acceptance or linked deployment success.</p>', 'A status message is more useful when we can trace its evidence. For T1, the sample contains a gate pass, review approval and merged task status, supported by the reduced sample state. The reporting code can also assemble feature coverage, QA rounds, usage and rulings for full runs. But this bundled trace lacks linked feature-level QA and deployment evidence. We preserve that gap. Consistently formatted phase summaries are a proposed improvement, not something newly implemented for this deck.',28)
add('Failure gets<br>a next step.', label('BOUNDED RECOVERY')+'<h1>Failure gets<br><em>a next step.</em></h1><div class="recovery"><div class="attempt fail"><span>ATTEMPT 1</span><h3>Review rejected</h3><p>Cleanup captures stale refs.</p></div><div class="connector">→<small>feedback</small></div><div class="attempt fail"><span>ATTEMPT 2</span><h3>Review rejected</h3><p>Existing effects replay on mount.</p></div><div class="connector">→<small>feedback</small></div><div class="attempt pass"><span>ATTEMPT 3</span><h3>Approved + merged</h3><p>Recorded task outcome.</p></div></div><div class="example"><span>ACTUAL SAMPLE · T5 / PACKETS + EFFECTS LAYERS</span><strong>Retry → escalate when required → park when exhausted.</strong></div>', 'The recording contains a useful recovery example. Task T5, packets and effects layers, passed its task gate but received two review rejections. The concerns involved captured references and replaying existing effects. The third attempt was approved and merged. That shows why passing checks and passing review are different milestones. More broadly, the factory bounds retries, can escalate or park tasks, and persists state for resume. We are not claiming this particular example escalated; the recorded fact is three attempts ending in a merge.',30)
add('Keep humans<br>in the driving seat.', label('HUMAN STEERING')+'<h1>Keep humans<br><em>in the driving seat.</em></h1><div class="steer-actions"><strong>Stop.</strong><strong>Resume.</strong><strong>Iterate.</strong></div><div class="steering-example"><span>ILLUSTRATIVE OPERATOR NOTE</span><blockquote>“Make task creation<br>keyboard accessible.”</blockquote><p>Notes reach the agent on its next turn.</p></div><div class="steer-image">'+img('realm-agent-detail.png')+'</div><p class="steer-foot">Lifecycle controls + agent notes + backlog. Mandatory approval at every phase is not implemented.</p>', 'Delegation should still leave useful ways to steer. FORGE supports stopping and resuming a run, adding notes or backlog work, and issuing iteration requests. For example, an operator could ask for keyboard-accessible task creation. That sentence is illustrative; we did not send it as part of this recording. In live mode, notes reach the agent on its next turn. The screenshot shows the real agent panel. This is operator steering, not mandatory human approval at every handoff.',28)
add('Jev advises. FORGE executes.', '<img class="reference-architecture" src="assets/architecture.png">', 'There are two distinct paths. At the top, deterministic code controls execution: it takes the task plan, assigns eligible work to specialist agents and applies quality stages. Human controls and recorded events make the workflow steerable and visible. Below, Jev is an experimental task-owner recommender through TypeSafe. It receives a locally approved summary and the allowed roles, suggests an owner, and logs an advisory result. It cannot assign work or change the workflow. Today the only allowed role is dev, so this proves no cross-role routing advantage. Broader evaluation is future work.',33)
add('Watch the team.<br>Then inspect the work.', label('FRONTEND WALKTHROUGH')+'<h1>Watch your <em>AI team work.</em></h1><div class="demo-video"><img src="assets/realm-working.png" class="video-poster"><video controls preload="metadata" poster="assets/realm-working.png" src="assets/agents-working.mp4"></video></div><div class="demo-side"><div><span>DEVELOPER</span><strong>T1 · Proxy server</strong><p>Inspect tool activity.</p></div><div><span>REVIEWER</span><strong>Task verdict</strong><p>Inspect approval or feedback.</p></div><div><span>TASK BOARD</span><strong>Workflow status</strong><p>Follow the handoff.</p></div><a class="live-link" href="http://127.0.0.1:4300/office/">OPEN LIVE CONSOLE ↗</a></div><div class="demo-caption">Embedded recording: actual frontend + recorded build events · not a fresh live AI run</div>', 'Now watch the actual frontend. The clip shows the factory world, a developer activity panel, task details and the board, driven by the existing sample recording. Point to the agent, its assigned work, and a recorded tool event; then follow the task into review. For a running factory, switch to the local console and inspect the same views against live events. The button requires the console to be running. The recording is the offline fallback. Don’t just ask AI to code. Give AI a team, and make its work visible.',40)
# Expanded read-only walkthrough of a real completed run and its actual documents.
for slide,seconds in zip(S,[20,27,27,27,27,27,27,27,31,60]):slide['seconds']=seconds
S[9]['body'] = label('WORKFLOW + DOCUMENT WALKTHROUGH')+'<h1>Follow the work. <em>Inspect the evidence.</em></h1><div class="demo-video"><img src="assets/complete-demo-poster.png" class="video-poster"><video controls preload="metadata" poster="assets/complete-demo-poster.png" src="assets/agents-working.mp4"></video></div><div class="demo-side"><div><span>KANBAN WORKFLOW</span><strong>Board → handoffs → timeline</strong></div><div><span>AGENT DOCUMENTS</span><strong>PRD → architecture → design</strong></div><div><span>QUALITY + DELIVERY</span><strong>QA → security → deployment</strong></div><div><span>RUN EVIDENCE</span><strong>Report → metrics → lessons</strong></div><a class="live-link" href="http://127.0.0.1:4300/office/?run=wheels2go-shadow-20261103-091012&amp;replay=1">OPEN RUN CONSOLE ↗</a></div><div class="demo-caption">Wheels2Go replay · actual UI captures + real documents · edited walkthrough · no new AI execution</div>'
S[9]['notes'] = 'This final walkthrough uses the actual Wheels2Go run console in replay mode. First inspect the agent activity, Kanban board and task history, then the handoffs and timeline. The document vault shows the real Product PRD, architecture, design specification, task plan and shared contracts. Next are QA evidence, security findings and the deployment record. Finally inspect the run report, recorded metrics, cross-run lessons and decision ledger. No research document exists in this run, and developers are represented by task/code activity rather than invented reports. This is FORGE’s existing task board, with the board, handoff and timeline views requested for this demo. The companion video preserves the longer walkthrough. Give AI a team, and make its work visible.'
# Presenter View notes are Mongolian; slide artwork stays in English.
notes_mn=json.loads((P/'notes-mn.json').read_text())
for slide,note in zip(S,notes_mn):slide['notes']=note
assert sum(s['seconds'] for s in S)==300
